'use client';

import type { HTMLAttributes } from 'react';
import { useEffect, useRef, useState } from 'react';
import { cx } from '@/utils/cx';

export type AvatarSize = 'xs' | 'sm' | 'md' | 'lg';
export type AvatarColor = 'neutral' | 'blue' | 'lime' | 'pink';

export type AvatarProps = Omit<HTMLAttributes<HTMLSpanElement>, 'color'> & {
  size?: AvatarSize;
  color?: AvatarColor;
  initials?: string;
  src?: string;
  alt?: string;
};

export function Avatar({ size = 'md', color = 'neutral', initials, src, alt, className, ...props }: AvatarProps) {
  const [failedSource, setFailedSource] = useState<string | null>(null);
  const imageRef = useRef<HTMLImageElement>(null);
  const showImage = Boolean(src && src !== failedSource);

  useEffect(() => {
    const image = imageRef.current;
    if (!image || !src) return;
    const fail = () => setFailedSource(src);
    if (image.complete && image.naturalWidth === 0) fail();
    image.addEventListener('error', fail);
    return () => image.removeEventListener('error', fail);
  }, [src, showImage]);

  return (
    <span role="img" aria-label={alt || initials || 'Avatar'} data-size={size} data-color={color} className={cx('ui-avatar', className)} {...props}>
      <span className="ui-avatar__initials" aria-hidden="true">{initials}</span>
      {showImage && <img ref={imageRef} src={src} alt="" aria-hidden="true" loading="lazy" decoding="async" onError={() => setFailedSource(src!)} />}
    </span>
  );
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

'use client';

import { createContext, useContext, useLayoutEffect, useRef, useState } from 'react';
import type { ComponentProps, ReactNode } from 'react';
import { Button as AriaButton, Dialog, DialogTrigger, Popover } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { IconButton, type IconButtonProps } from '@/components/base/buttons/icon-button';

const DropdownContext = createContext<{ close: () => void; isOpen: boolean } | null>(null);

export interface DropdownProps {
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  children: ReactNode;
}

export function Dropdown({ isOpen, defaultOpen = false, onOpenChange, children }: DropdownProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = isOpen === undefined ? internalOpen : isOpen;
  function setOpen(next: boolean) {
    if (isOpen === undefined) setInternalOpen(next);
    onOpenChange?.(next);
  }
  return <DropdownContext.Provider value={{ close: () => setOpen(false), isOpen: open }}><DialogTrigger isOpen={open} onOpenChange={setOpen}>{children}</DialogTrigger></DropdownContext.Provider>;
}

export type DropdownTriggerProps = Omit<ComponentProps<typeof AriaButton>, 'className'> & { className?: string };
export function DropdownTrigger({ className, ...props }: DropdownTriggerProps) {
  return <AriaButton {...props} className={cx('ui-dropdown-trigger', className)} />;
}

// Icon triggers use the same dimensions as every other icon button.
export function DropdownIconTrigger(props: IconButtonProps) {
  return <IconButton {...props} />;
}

export interface DropdownPopoverProps {
  'aria-label': string;
  placement?: ComponentProps<typeof Popover>['placement'];
  triggerRef?: ComponentProps<typeof Popover>['triggerRef'];
  isOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  offset?: number;
  className?: string;
  children: ReactNode;
}

export function DropdownPopover({ 'aria-label': ariaLabel, placement = 'bottom start', triggerRef, isOpen, onOpenChange, offset = 5, className, children }: DropdownPopoverProps) {
  const context = useContext(DropdownContext);
  const open = isOpen ?? context?.isOpen;
  const dialogRef = useRef<HTMLElement>(null);
  useLayoutEffect(() => {
    if (!open) return;
    // An interrupted exit keeps the popover mounted, so its focus scope does
    // not mount again. Restore focus inside on every opening, including reopens.
    const frame = requestAnimationFrame(() => {
      const dialog = dialogRef.current;
      if (dialog && (!dialog.contains(document.activeElement) || document.activeElement === dialog)) {
        (dialog.querySelector<HTMLElement>('[role="menuitem"]:not(:disabled), input:not([disabled]), textarea:not([disabled])') ?? dialog).focus({ preventScroll: true });
      }
    });
    return () => cancelAnimationFrame(frame);
  }, [open]);
  return <Popover placement={placement} data-align={placement.split(' ')[1] ?? 'center'} triggerRef={triggerRef} isOpen={isOpen} onOpenChange={onOpenChange} offset={offset} className={cx('ui-dropdown-popover', className)}>{({isExiting})=><div className="ui-dropdown-content" onKeyDown={event => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    // Native text/range controls keep their own navigation keys.
    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return;
    const items = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('.ui-dropdown-item:not(:disabled), [role="menuitem"]:not(:disabled)'));
    if (!items.length) return;
    event.preventDefault();
    const active = items.indexOf(document.activeElement as HTMLButtonElement);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : event.key === 'ArrowDown' ? (active + 1) % items.length : (active - 1 + items.length) % items.length;
    items[next].focus();
  }}><Dialog inert={isExiting} ref={dialogRef} aria-label={ariaLabel} className="ui-dropdown-dialog"><div>{children}</div></Dialog></div>}</Popover>;
}

export function DropdownGroup({ label, children, className }: { label?: string; children: ReactNode; className?: string }) {
  return <div className={cx('ui-dropdown-group', className)}>{label && <span className="ui-dropdown-group__label">{label}</span>}<div className="ui-dropdown-group__items">{children}</div></div>;
}

export interface DropdownItemProps {
  selected?: boolean;
  isDisabled?: boolean;
  closeOnSelect?: boolean;
  onSelect?: () => void;
  className?: string;
  children: ReactNode;
}

export function DropdownItem({ selected, isDisabled, closeOnSelect = true, onSelect, className, children }: DropdownItemProps) {
  const context = useContext(DropdownContext);
  return <button type="button" disabled={isDisabled} aria-pressed={selected || undefined} className={cx('ui-dropdown-item', className)} onClick={() => { onSelect?.(); if (closeOnSelect) context?.close(); }}>{children}</button>;
}

export function DropdownDivider({ className }: { className?: string }) {
  return <div role="separator" aria-orientation="horizontal" className={cx('ui-dropdown-divider', className)} />;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { RiAddLine, RiArrowLeftSLine, RiArrowRightLine, RiArrowRightSLine, RiCloseLine, RiGlobalLine, RiGroupLine, RiInbox2Line, RiNotification3Line, RiTimeLine, RiVideoChatLine } from '@remixicon/react';
import { Dropdown, DropdownIconTrigger, DropdownPopover } from '@/components/base/dropdown/dropdown';
import { NotificationCenter, type InboxNotification } from '@/components/blocks/notification-center/notification-center';
import { cx } from '@/utils/cx';

export type CalendarEvent = {
  id: string;
  title: string;
  date: string;
  time?: string;
  endTime?: string;
  color?: 'blue' | 'pink' | 'lime' | 'purple' | 'cyan';
  description?: string;
  attendees?: string[];
  meetingUrl?: string;
  meetingCode?: string;
  meetingProvider?: string;
  timezone?: string;
  reminder?: string;
};
export type CalendarNotification = Pick<InboxNotification, 'id' | 'title'> & Partial<Pick<InboxNotification, 'category' | 'time' | 'avatar' | 'status' | 'action' | 'secondaryAction'>> & { detail?: string; read?: boolean };
export type CalendarProps = {
  events: CalendarEvent[];
  notifications?: CalendarNotification[];
  month?: Date;
  defaultMonth?: Date;
  onNotificationReadChange?: (id: string, read: boolean) => void;
  onMonthChange?: (month: Date) => void;
  onNewEvent?: (date?: string) => void;
  onEventClick?: (event: CalendarEvent) => void;
  onJoinMeeting?: (event: CalendarEvent) => void;
  className?: string;
};

const weekdays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const keyOf = (date: Date) => [date.getFullYear(), String(date.getMonth() + 1).padStart(2, '0'), String(date.getDate()).padStart(2, '0')].join('-');
const monthName = (date: Date) => new Intl.DateTimeFormat('en', { month: 'long', year: 'numeric' }).format(date);
const eventDate = (value: string) => new Intl.DateTimeFormat('en', { weekday: 'short', month: 'short', day: 'numeric' }).format(new Date(value + 'T12:00:00'));
function durationText(start: string, end: string) {
  const [startHours, startMinutes] = start.split(':').map(Number);
  const [endHours, endMinutes] = end.split(':').map(Number);
  const minutes = ((endHours * 60 + endMinutes) - (startHours * 60 + startMinutes) + 1440) % 1440;
  return [Math.floor(minutes / 60) ? Math.floor(minutes / 60) + 'h' : '', minutes % 60 ? minutes % 60 + 'm' : ''].join('');
}

export function Calendar({ events, notifications = [], month, defaultMonth = new Date(), onMonthChange, onNewEvent, onEventClick, onJoinMeeting, onNotificationReadChange, className }: CalendarProps) {
  const [internalMonth, setInternalMonth] = useState(new Date(defaultMonth.getFullYear(), defaultMonth.getMonth(), 1));
  const [selected, setSelected] = useState<CalendarEvent | null>(null);
  const [feed, setFeed] = useState<'notifications' | 'inbox' | null>(null);
  const [readIds, setReadIds] = useState<string[]>([]);
  const [popoverPosition, setPopoverPosition] = useState({ left: 0, top: 0 });
  const gridRef = useRef<HTMLDivElement>(null);
  const anchorRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const current = month ?? internalMonth;
  const first = new Date(current.getFullYear(), current.getMonth(), 1);
  const gridStart = new Date(first.getFullYear(), first.getMonth(), 1 - first.getDay());
  const days = Array.from({ length: 42 }, (_, index) => new Date(gridStart.getFullYear(), gridStart.getMonth(), gridStart.getDate() + index));
  const byDate = useMemo(() => {
    const grouped = new Map<string, CalendarEvent[]>();
    for (const event of events) grouped.set(event.date, [...(grouped.get(event.date) ?? []), event]);
    return grouped;
  }, [events]);
  const notificationItems: InboxNotification[] = notifications.map(item => ({ ...item, category: item.category ?? 'activity', time: item.time ?? '', description: item.detail ?? '', unread: !item.read && !readIds.includes(item.id) }));
  const unread = notificationItems.filter(item => item.unread).length;
  function markRead(ids: string[]) {
    setReadIds(current => [...new Set([...current, ...ids])]);
    ids.forEach(id => onNotificationReadChange?.(id, true));
  }
  const monthEvents = events.filter(item => item.date.slice(0, 7) === keyOf(first).slice(0, 7)).slice(0, 4);

  function move(offset: number) {
    const next = new Date(first.getFullYear(), first.getMonth() + offset, 1);
    if (!month) setInternalMonth(next);
    onMonthChange?.(next);
    setSelected(null);
    setFeed(null);
  }

  function positionPopover() {
    const anchor = anchorRef.current?.getBoundingClientRect();
    if (!anchor) return;
    const width = Math.min(302, window.innerWidth - 24);
    const left = window.innerWidth < 680 ? Math.max(12, (window.innerWidth - width) / 2) : Math.min(window.innerWidth - width - 12, anchor.right + 8);
    const gridTop = gridRef.current?.getBoundingClientRect().top ?? anchor.top;
    const desiredTop = Math.max(gridTop, anchor.top - 104);
    const actualHeight = popoverRef.current?.getBoundingClientRect().height ?? 412;
    const top = Math.max(12, Math.min(desiredTop, window.innerHeight - actualHeight - 12));
    setPopoverPosition({ left, top });
  }

  useLayoutEffect(() => {
    if (!selected) return;
    positionPopover();
    window.addEventListener('resize', positionPopover);
    window.addEventListener('scroll', positionPopover, true);
    return () => {
      window.removeEventListener('resize', positionPopover);
      window.removeEventListener('scroll', positionPopover, true);
    };
  }, [selected]);

  useEffect(() => {
    if (!selected) return;
    function dismiss(event: PointerEvent) {
      const target = event.target as Node;
      if (!popoverRef.current?.contains(target) && !gridRef.current?.contains(target)) setSelected(null);
    }
    function onKeyDown(event: KeyboardEvent) { if (event.key === 'Escape') setSelected(null); }
    document.addEventListener('pointerdown', dismiss);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('pointerdown', dismiss);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [selected]);

  function openEvent(event: CalendarEvent, anchor: HTMLButtonElement) {
    anchorRef.current = anchor;
    setSelected(event);
    setFeed(null);
    onEventClick?.(event);
  }

  return <div className={cx('ui-calendar', className)}>
    <div className="ui-calendar__head">
      <h2>{monthName(first)}</h2>
      <div className="ui-calendar__head-actions">
        <div className="ui-calendar__feed-wrap">
          <Dropdown isOpen={feed === 'notifications'} onOpenChange={open => setFeed(current => open ? 'notifications' : current === 'notifications' ? null : current)}>
            <DropdownIconTrigger icon={RiNotification3Line} aria-label="Notifications" badge={unread} />
            <DropdownPopover aria-label="Calendar notifications" placement="bottom end" offset={8} className="ui-calendar__notifications-popover">
              <NotificationCenter items={notificationItems} onReadChange={id => markRead([id])} onMarkAllRead={() => markRead(notificationItems.filter(item => item.unread).map(item => item.id))} />
            </DropdownPopover>
          </Dropdown>
          <Dropdown isOpen={feed === 'inbox'} onOpenChange={open => setFeed(current => open ? 'inbox' : current === 'inbox' ? null : current)}>
            <DropdownIconTrigger icon={RiInbox2Line} aria-label="Inbox" />
            <DropdownPopover aria-label="Events this month" placement="bottom end" offset={8} className="ui-calendar__inbox-popover"><div className="ui-calendar__inbox"><strong>Events this month</strong>{monthEvents.length ? monthEvents.map(item => <div key={item.id}><b>{item.title}</b><small>{eventDate(item.date)}</small></div>) : <p>No events this month</p>}</div></DropdownPopover>
          </Dropdown>
        </div>
        <div className="ui-calendar__tools"><button type="button" aria-label="Previous month" onClick={() => move(-1)}><RiArrowLeftSLine size={18} aria-hidden /></button><span>{monthName(first)}</span><button type="button" aria-label="Next month" onClick={() => move(1)}><RiArrowRightSLine size={18} aria-hidden /></button></div>
        {onNewEvent && <button className="ui-calendar__new" type="button" onClick={() => onNewEvent()}><RiAddLine size={17} aria-hidden /> New event</button>}
      </div>
    </div>
    <div className="ui-calendar__scroller"><div className="ui-calendar__grid" ref={gridRef}>
      <div className="ui-calendar__weekdays">{weekdays.map(day => <span key={day}>{day}</span>)}</div>
      <div className="ui-calendar__days">{days.map(date => {
        const key = keyOf(date);
        const dayEvents = byDate.get(key) ?? [];
        const outside = date.getMonth() !== first.getMonth();
        return <div key={key} className="ui-calendar__day" data-outside={outside || undefined} data-today={key === keyOf(new Date()) || undefined}>
          <button className="ui-calendar__day-number" type="button" disabled={!onNewEvent} aria-label={new Intl.DateTimeFormat('en', { dateStyle: 'full' }).format(date)} onClick={() => { setSelected(null); onNewEvent?.(key); }}>{date.getDate()}</button>
          <div className="ui-calendar__events">
            {dayEvents.length > 4 && <button className="ui-calendar__more" type="button" onClick={event => openEvent(dayEvents[4], event.currentTarget)}>+{dayEvents.length - 4} more</button>}
            {dayEvents.slice(0, 4).map(event => <button key={event.id} type="button" data-color={event.color ?? 'blue'} aria-label={[event.title, key, event.time].filter(Boolean).join(' · ')} onClick={click => openEvent(event, click.currentTarget)}><span>{event.title}</span>{event.time && <time>{event.time}</time>}</button>)}
          </div>
        </div>;
      })}</div>
    </div></div>
    {selected && typeof document !== 'undefined' && createPortal(<aside className="ui-calendar__popover" ref={popoverRef} role="dialog" aria-modal="false" aria-label={selected.title + ' details'} style={popoverPosition}>
      <div className="ui-calendar__popover-head"><div><strong>{selected.title}</strong><span>{eventDate(selected.date)}</span></div><button type="button" aria-label="Close event details" onClick={() => setSelected(null)}><RiCloseLine size={17} /></button></div>
      {selected.meetingProvider && <div className="ui-calendar__popover-row ui-calendar__popover-meeting"><RiVideoChatLine size={16} aria-hidden /><span>{selected.meetingProvider}</span>{selected.meetingCode && <code>{selected.meetingCode}</code>}{(selected.meetingUrl || onJoinMeeting) && (selected.meetingUrl ? <a href={selected.meetingUrl} target="_blank" rel="noreferrer">Join</a> : <button type="button" onClick={() => onJoinMeeting?.(selected)}>Join</button>)}</div>}
      {selected.time && <div className="ui-calendar__popover-row"><RiTimeLine size={16} aria-hidden /><span>{selected.time}</span>{selected.endTime && <><RiArrowRightLine size={16} aria-hidden /><span>{selected.endTime}</span></>}{selected.endTime && <small>{durationText(selected.time, selected.endTime)}</small>}</div>}
      {selected.timezone && <div className="ui-calendar__popover-row"><RiGlobalLine size={16} aria-hidden /><span>{selected.timezone}</span></div>}
      {selected.attendees?.length ? <div className="ui-calendar__popover-row ui-calendar__popover-participants"><div className="ui-calendar__popover-section-title"><RiGroupLine size={16} aria-hidden /><span>Participants</span></div>{selected.attendees.map((person, index) => <div className="ui-calendar__person" key={person}><span data-index={index % 4}>{person[0]?.toUpperCase()}</span>{person}</div>)}</div> : null}
      {selected.reminder && <div className="ui-calendar__popover-row"><RiNotification3Line size={16} aria-hidden /><span>Reminders</span><b>{selected.reminder}</b></div>}
      {selected.description && <p className="ui-calendar__popover-description">{selected.description}</p>}
    </aside>, document.body)}
  </div>;
}

'use client';

import { useState } from 'react';
import { motion, AnimatePresence, useReducedMotion } from 'motion/react';
import { RiCheckDoubleLine, RiNotification3Line } from '@remixicon/react';
import { Avatar } from '@/components/base/avatar/avatar';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type InboxNotification = { id: string; category: 'mentions' | 'system' | 'activity'; title: string; description: string; time: string; group?: string; unread?: boolean; status?: 'neutral' | 'information' | 'success' | 'error'; icon?: IconComponent; avatar?: { src?: string; alt: string; initials: string }; action?: { label: string; variant?: 'primary' | 'secondary' | 'danger'; onPress: () => void }; secondaryAction?: { label: string; variant?: 'primary' | 'secondary' | 'danger'; onPress: () => void } };
type Filter = 'all' | 'mentions' | 'system';
export type NotificationCenterProps = { items: InboxNotification[]; tab?: Filter; defaultTab?: Filter; onTabChange?: (tab: Filter) => void; onReadChange?: (id: string, read: boolean) => void; onMarkAllRead?: () => void; onAction?: (notificationId: string, actionLabel: string) => void; className?: string };
export function NotificationCenter({ items, tab, defaultTab = 'all', onTabChange, onReadChange, onMarkAllRead, onAction, className }: NotificationCenterProps) {
  const [internalFilter, setInternalFilter] = useState<Filter>(defaultTab);
  const filter = tab ?? internalFilter;
  const [readIds, setReadIds] = useState<string[]>([]);
  const reducedMotion = useReducedMotion();
  const unread = items.filter(item => item.unread && !readIds.includes(item.id)).length;
  const visible = items.filter(item => filter === 'all' || item.category === filter);
  function markRead(id: string) { if (readIds.includes(id)) return; setReadIds(current => [...current,id]); onReadChange?.(id,true); }
  function markAll() { if (!unread) return; setReadIds(items.map(item => item.id)); onMarkAllRead?.(); }
  return <div className={cx('ui-notification-center', className)}><header><div><h2>Notifications</h2><p>{unread} unread</p></div><button type="button" aria-disabled={!unread} onClick={markAll}>Mark all read</button></header><div className="ui-notification-center__tabs" role="tablist" aria-label="Notification filter">{(['all','mentions','system'] as const).map(item => <button key={item} type="button" role="tab" aria-selected={filter === item} onClick={() => { if (tab === undefined) setInternalFilter(item); onTabChange?.(item); }}>{item[0].toUpperCase()+item.slice(1)} <span>{item === 'all' ? items.length : items.filter(entry => entry.category === item).length}</span></button>)}</div><div className="ui-notification-center__list"><AnimatePresence mode="popLayout" initial={false}>{visible.length ? visible.map(item => {
    const Icon = item.icon ?? RiNotification3Line;
    const actions = [item.action, item.secondaryAction].filter(action => action !== undefined);
    return <motion.article key={item.id} className="ui-notification-center__item" layout initial={reducedMotion ? false : { opacity: 0, y: 8, filter: 'blur(3px)' }} animate={{ opacity: 1, y: 0, filter: 'blur(0px)' }} exit={reducedMotion ? undefined : { opacity: 0, y: -8, filter: 'blur(3px)' }} transition={{ duration: reducedMotion ? 0 : .28, ease: [0.2, .75, .25, 1] }} data-unread={item.unread && !readIds.includes(item.id) || undefined} data-status={item.status ?? 'neutral'}><div className="ui-notification-center__avatar">{item.avatar ? <Avatar size="md" src={item.avatar.src} alt={item.avatar.alt} initials={item.avatar.initials} /> : <Icon size={20} aria-hidden />}</div><div className="ui-notification-center__copy"><div className="ui-notification-center__headline"><strong>{item.title}</strong><div className="ui-notification-center__meta"><time>{item.time}</time>{item.unread && !readIds.includes(item.id) && <button type="button" aria-label={`Mark ${item.title} as read`} onClick={() => markRead(item.id)} />}</div></div><p>{item.description}</p>{actions.length > 0 && <div className="ui-notification-center__actions">{actions.map((action, index) => <button key={`${item.id}-${index}`} type="button" data-variant={action.variant ?? (index === 0 ? 'primary' : 'secondary')} onClick={() => { action.onPress(); onAction?.(item.id, action.label); markRead(item.id); }}>{action.label}</button>)}</div>}</div></motion.article>;
  }) : <div className="ui-notification-center__empty" key="empty"><RiCheckDoubleLine size={25} aria-hidden /><strong>All caught up</strong><span>There’s nothing new in this view.</span></div>}</AnimatePresence></div></div>;
}

'use client';

import { useCallback, useSyncExternalStore } from 'react';

export function useMediaQuery(query: string) {
  const subscribe = useCallback((notify: () => void) => {
    const media = window.matchMedia(query);
    media.addEventListener('change', notify);
    return () => media.removeEventListener('change', notify);
  }, [query]);
  const snapshot = useCallback(() => window.matchMedia(query).matches, [query]);
  return useSyncExternalStore(subscribe, snapshot, () => false);
}

